def pool_for(chain_id: int, tin: str, tout: str) -> str | None:
    a, b = sorted((tin.lower(), tout.lower()))
    return _BAL_POOLS.get((chain_id, a, b))


def _call_deltas(eth_call, swaps, assets):
    funds = (_ZERO, False, _ZERO, False)
    data = _QBS_SEL + _abi_encode(
        ["uint8", "(bytes32,uint256,uint256,uint256,bytes)[]", "address[]", "(address,bool,address,bool)"],
        [0, swaps, assets, funds],
    )
    r = eth_call(VAULT, "0x" + data.hex())
    if not r:
        return None
    rb = bytes.fromhex(r[2:] if isinstance(r, str) and r.startswith("0x") else r) if isinstance(r, str) else bytes(r)
    return _abi_decode(["int256[]"], rb)[0]


def _quote_direct(eth_call, pid, tin, tout, amount) -> int:
    try:
        swaps = [(bytes.fromhex(pid[2:]), 0, 1, int(amount), b"")]
        assets = [Web3.to_checksum_address(tin), Web3.to_checksum_address(tout)]
        d = _call_deltas(eth_call, swaps, assets)
        out = -int(d[1]) if d else 0
        return out if out > 0 else 0
    except Exception:
        return 0


def _quote_2hop(eth_call, p1, p2, tin, hub, tout, amount) -> int:
    try:
        swaps = [
            (bytes.fromhex(p1[2:]), 0, 1, int(amount), b""),
            (bytes.fromhex(p2[2:]), 1, 2, 0, b""),  # 0 amount = use full output of prior step
        ]
        assets = [Web3.to_checksum_address(tin), Web3.to_checksum_address(hub), Web3.to_checksum_address(tout)]
        d = _call_deltas(eth_call, swaps, assets)
        out = -int(d[2]) if d and len(d) >= 3 else 0
        return out if out > 0 else 0
    except Exception:
        return 0


def best_route(eth_call, chain_id: int, tin: str, tout: str, amount: int):
    """Return (out, route) with the most output, or None. route is
    ('direct', poolId) or ('hop', p1, p2, hub)."""
    if amount <= 0:
        return None
    best_out, best = 0, None
    pid = pool_for(chain_id, tin, tout)
    if pid:
        o = _quote_direct(eth_call, pid, tin, tout, amount)
        if o > best_out:
            best_out, best = o, ("direct", pid)
    tl, ol = tin.lower(), tout.lower()
    for hub in _HUBS.get(chain_id, []):
        if hub in (tl, ol):
            continue
        p1 = pool_for(chain_id, tin, hub)
        p2 = pool_for(chain_id, hub, tout)
        if p1 and p2:
            o = _quote_2hop(eth_call, p1, p2, tin, hub, tout, amount)
            if o > best_out:
                best_out, best = o, ("hop", p1, p2, hub)
    return (best_out, best) if best else None


def build_route(route, tin: str, tout: str, amount: int, min_out: int, recipient: str, deadline: int):
    """Return (approve_calldata, swap_calldata) hex for the given route."""
    tin_cs = Web3.to_checksum_address(tin)
    tout_cs = Web3.to_checksum_address(tout)
    rec = Web3.to_checksum_address(recipient)
    approve = "0x" + (_APPROVE_SEL + _abi_encode(["address", "uint256"], [VAULT, int(amount)])).hex()
    funds = (rec, False, rec, False)
    if route[0] == "direct":
        pid = route[1]
        single = (bytes.fromhex(pid[2:]), 0, tin_cs, tout_cs, int(amount), b"")
        swap = _SWAP_SEL + _abi_encode(
            ["(bytes32,uint8,address,address,uint256,bytes)", "(address,bool,address,bool)", "uint256", "uint256"],
            [single, funds, int(min_out), int(deadline)],
        )
        return approve, "0x" + swap.hex()
    # 2-hop batchSwap
    _, p1, p2, hub = route
    hub_cs = Web3.to_checksum_address(hub)
    swaps = [
        (bytes.fromhex(p1[2:]), 0, 1, int(amount), b""),
        (bytes.fromhex(p2[2:]), 1, 2, 0, b""),
    ]
    assets = [tin_cs, hub_cs, tout_cs]
    limits = [int(amount), 0, -int(min_out)]  # +max in (tin), 0 hub, -min out (tout)
    batch = _BATCH_SEL + _abi_encode(
        ["uint8", "(bytes32,uint256,uint256,uint256,bytes)[]", "address[]",
         "(address,bool,address,bool)", "int256[]", "uint256"],
        [0, swaps, assets, funds, limits, int(deadline)],
    )
    return approve, "0x" + batch.hex()
